UPDATE public.comexlab_news n
 SET title_pt=v.title_pt,summary_pt=v.summary_pt,translation_status='ready',
 translation_provider='revisao-editorial',translated_at=NOW(),updated_at=NOW()
 FROM (VALUES (1,'Acordos comerciais da UE continuam beneficiando empresas europeias','Relatório da Comissão Europeia aponta que a rede crescente de acordos comerciais da União Europeia facilita o acesso das empresas a novos mercados de exportação e torna mais previsíveis os investimentos e as operações comerciais.'),(2,'Comissão Europeia aplica medidas contra importações de proteína de ervilha da China','A Comissão Europeia impôs direitos antidumping sobre importações de proteína de ervilha provenientes da China para a União Europeia.'),(3,'União Europeia e Filipinas alcançam entendimento substancial sobre acordo comercial','A União Europeia e as Filipinas avançaram significativamente nas negociações de um acordo de livre-comércio destinado a estreitar os vínculos econômicos com o parceiro do Sudeste Asiático.'),(4,'União Europeia e Filipinas divulgam declaração conjunta sobre acordo comercial','A União Europeia e as Filipinas anunciaram um entendimento substancial sobre um acordo de livre-comércio, considerado um marco importante para ambas as partes.'),(5,'Demanda por medidas de defesa comercial permaneceu elevada na UE em 2025','Relatório informa que a Comissão Europeia abriu em 2025 um número de investigações de defesa comercial acima da média, diante da persistente demanda por ações contra práticas comerciais consideradas desleais.'),(6,'UE impõe salvaguardas provisórias à importação de aço elétrico de grão orientado','A Comissão Europeia adotou medidas de salvaguarda provisórias para importações de aço elétrico de grão orientado, utilizando cotas tarifárias associadas a limites de preço.'),(7,'UE abre licitação para visitas técnicas e análises sanitárias e fitossanitárias','O edital EC-TRADE/2026/OP/0027 busca contratar a organização de visitas de representantes de países terceiros à União Europeia e análises de acesso a mercados na área sanitária e fitossanitária.'),(8,'União Europeia atualiza lista de controle de produtos de uso duplo em 2026','Em 14 de setembro de 2026, a Comissão Europeia adotou regulamento delegado para atualizar a lista de itens de uso duplo sujeitos a controles de exportação, prevista no anexo I do Regulamento (UE) 2021/821.'),(9,'Comissão apresenta acordo de facilitação de investimentos UE–Equador ao Conselho','A Comissão Europeia encaminhou ao Conselho a proposta de Acordo de Facilitação de Investimentos Sustentáveis entre a União Europeia e o Equador, para assinatura e conclusão.'),(10,'Comissão apresenta ao Conselho acordo comercial entre União Europeia e Índia','A Comissão Europeia apresentou ao Conselho propostas para autorizar a assinatura e a conclusão de um acordo de livre-comércio entre a União Europeia e a Índia.'),(11,'Comissão abre consulta sobre revisão de instrumento de compras públicas internacionais','A Comissão Europeia abriu consulta pública sobre a primeira revisão do Instrumento de Contratação Pública Internacional, conhecido pela sigla IPI.'),(12,'UE celebra entrada do Camboja em mecanismo provisório de recursos da OMC','A União Europeia saudou a decisão do Camboja de aderir ao mecanismo multipartes de arbitragem provisória de apelação da OMC, voltado à preservação de um sistema multilateral de comércio baseado em regras.'),(13,'UE define provas exigidas de importadores sobre origem de produção do aço','A Comissão Europeia estabeleceu os tipos de documentos que importadores deverão apresentar para comprovar o país em que o aço foi fundido e vazado, conforme as regras europeias para produtos siderúrgicos abrangidos.'),(14,'Observatório da China: UE contrata monitoramento de política econômica','O procedimento EC-TRADE/2025/OP/0031 trata do monitoramento de políticas econômicas chinesas e seus efeitos nas relações UE–China, incluindo a criação e a manutenção de uma base de investimentos estrangeiros diretos.'),(15,'UE aplica direitos antidumping ao ácido tereftálico da Coreia do Sul e do México','A Comissão Europeia impôs direitos antidumping sobre importações de ácido tereftálico provenientes da Coreia do Sul e do México.'),(16,'Comissão abre licitação para dados de tarifas e procedimentos do Access2Markets','O edital EC-TRADE/2026/OP/0021 prevê a contratação de dados sobre tarifas, impostos, procedimentos e formalidades para a plataforma Access2Markets entre 2027 e 2030.'),(17,'União Europeia prorroga suspensão de medidas de reequilíbrio contra os EUA','A Comissão Europeia aprovou regulamento de execução que estende a suspensão de medidas comerciais de reequilíbrio da UE sobre exportações dos Estados Unidos para o bloco.'),(18,'Comissão consulta setor sobre produtos abrangidos por regulamento europeu do aço','A Comissão Europeia abriu consulta dirigida para recolher contribuições sobre quais produtos devem integrar o escopo do Regulamento do Aço da UE, em sua primeira revisão de abrangência.'),(19,'União Europeia aplica direitos antidumping a fios de poliamida da China','A Comissão Europeia impôs direitos antidumping sobre importações de fios de poliamida provenientes da China para a União Europeia.'),(20,'Aviso prévio de licitação para estudos sanitários e fitossanitários da UE','O aviso EC-TRADE/2026/OP/0027-PIN trata de contrato para organizar visitas de estudo e análises de acesso a mercados no campo sanitário e fitossanitário.'),(21,'UE e Costa do Marfim iniciam negociações para facilitar investimentos sustentáveis','A Comissão Europeia iniciou negociações com a Costa do Marfim para um acordo bilateral de facilitação de investimentos sustentáveis, conhecido pela sigla SIFA.'),(22,'Relações comerciais da UE com países em desenvolvimento apoiam crescimento sustentável','A Comissão Europeia e a Alta Representante da UE publicaram relatório sobre a aplicação do Sistema de Preferências Generalizadas, ferramenta comercial que apoia exportações de países em desenvolvimento para o bloco.'),(23,'União Europeia e Índia reforçam parceria em comércio e tecnologia','Representantes da União Europeia e da Índia realizaram, em Bruxelas, a terceira reunião do Conselho de Comércio e Tecnologia, reafirmando a cooperação em comércio, tecnologia e segurança.'),(24,'Comissão Europeia moderniza mecanismo de monitoramento das importações','Diante de desequilíbrios crescentes no comércio global, a Comissão Europeia está reformulando seu barômetro de importações, criado em 2025 para reunir dados atualizados sobre produtos importados.'),(25,'União Europeia apresenta três documentos para avançar na reforma da OMC','A União Europeia enviou três documentos à Organização Mundial do Comércio com propostas para orientar a reforma de seu funcionamento, durante uma fase mais aprofundada das discussões entre membros.'),(28,'Expansão da IA e resistência do comércio à crise no Oriente Médio melhoram projeções','O comércio mundial resistiu melhor do que o previsto às interrupções provocadas pelo conflito no Oriente Médio no primeiro semestre de 2026. Cadeias de suprimento se adaptaram, e investimentos em inteligência artificial impulsionaram o comércio de bens. A OMC elevou sua projeção para mercadorias, mas reduziu a de serviços, diante de impactos desiguais.'),(29,'Conselho Geral da OMC debate reforma, decisões ministeriais e negociações','Em reunião de 5 e 6 de outubro, integrantes da OMC discutiram a reforma da organização, os desdobramentos de conferências ministeriais e o andamento de negociações. A pauta incluiu comércio eletrônico, questões agrícolas e a preparação de futuras conferências.'),(30,'Iniciativa de sustentabilidade comercial avança no planejamento da 15ª Ministerial','Em 2 de outubro, participantes dos Debates Estruturados sobre Comércio e Sustentabilidade Ambiental discutiram um plano de trabalho para 2026 e 2027, com foco na 15ª Conferência Ministerial da OMC. Foram avaliadas prioridades, formas de trabalho e entregas possíveis.'),(31,'Grupo de pequenas empresas da OMC analisa propriedade intelectual e comércio','O grupo informal da OMC sobre micro, pequenas e médias empresas reuniu-se em 2 de outubro para debater como a propriedade intelectual pode ajudar negócios a inovar, crescer e acessar mercados externos. Houve apresentações sobre ferramentas e iniciativas para o segmento.'),(32,'Vice-diretor da OMC destaca resiliência do comércio internacional','Em fórum sobre comércio global em Montreux, o vice-diretor-geral DJ Nordquist afirmou que as funções da OMC ganham importância diante da geopolítica e da segurança econômica. Empresas precisam considerar exposição geopolítica, abastecimento e riscos regulatórios.'),(33,'Direção-geral da OMC manifesta preocupação com ritmo das negociações','Em reunião do Comitê de Negociações Comerciais, em 1º de outubro, membros da OMC avaliaram a agenda negociadora seis meses após a 14ª Conferência Ministerial e ouviram relatores sobre a evolução das diferentes frentes de negociação.'),(34,'Diálogo sobre plásticos da OMC inicia debates técnicos após a 14ª Ministerial','Integrantes do diálogo da OMC sobre poluição plástica e comércio sustentável discutiram soluções circulares, gestão de resíduos, plásticos descartáveis e medidas comerciais ligadas ao setor. O objetivo foi avançar para propostas técnicas mais concretas.'),(35,'Países-membros avaliam avanços recentes nas discussões sobre reforma da OMC','Em sessão de transparência de 30 de setembro, facilitadores relataram o andamento dos quatro eixos de reforma da OMC: fundamentos, decisões, desenvolvimento e condições justas de concorrência. Apesar do engajamento dos membros, ainda há trabalho a realizar.'),(36,'Competição acadêmica John H. Jackson sobre direito da OMC oferece webinars','Interessados na 25ª edição da competição acadêmica John H. Jackson, dedicada ao direito da OMC e lançada em setembro de 2026, foram convidados a participar de webinars preparatórios.'),(37,'Membros da OMC aprofundam debate sobre comércio e medidas climáticas','O Comitê de Comércio e Meio Ambiente reuniu-se em 28 e 29 de setembro para discutir relações entre comércio e clima, compatibilidade entre medidas climáticas e desafios para países em desenvolvimento. Também houve troca voluntária de informações e relatos sobre iniciativas ambientais.')) AS v(id,title_pt,summary_pt)
 WHERE n.id=v.id AND n.source_slug IN ('wto','ec') AND n.translation_status='pending';
